<template><form @submit.prevent="submit" class="space-y-4"><div><h1 class="text-2xl font-extrabold">Masuk ke Delcom Auction</h1><p class="text-sm text-slate-500 mt-1">Gunakan akun Delcom kamu.</p></div><input v-model="username" class="w-full border rounded-xl p-3" placeholder="Username"/><input v-model="password" type="password" class="w-full border rounded-xl p-3" placeholder="Password"/><button :disabled="loading" class="w-full bg-indigo-600 text-white rounded-xl p-3 font-semibold">{{loading?'Memproses...':'Masuk'}}</button><p class="text-sm text-center">Belum punya akun? <RouterLink class="text-indigo-600 font-semibold" to="/auth/register">Daftar</RouterLink></p></form></template><script setup>import {ref} from 'vue';import {RouterLink,useRouter} from 'vue-router';import {useAuthStore} from '../states/authStore';import {showErrorDialog} from '../../../helpers/toolsHelper';const username=ref(''),password=ref(''),loading=ref(false),auth=useAuthStore(),router=useRouter();async function submit(){if(!username.value||!password.value)return showErrorDialog('Username dan password wajib diisi');loading.value=true;try{await auth.signIn(username.value,password.value);router.push('/')}catch(e){showErrorDialog(e.message)}finally{loading.value=false}}</script>
